#nullable enable
using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.AI;using UnityEngine.Experimental.AI;using Unity.Collections;
namespace Frontier.Survivor;
internal sealed class NavigationLayer:IDisposable {
 sealed class Bake {internal NavMeshData Data=null!;internal AsyncOperation Op=null!;internal NavMeshDataInstance Instance;internal int AgentId;internal bool Published;}
 readonly List<Bake> bakes=new();readonly LeaseBag roots=new();readonly Il2CppSystem.Collections.Generic.List<NavMeshBuildSource> sources=new();internal bool Validated{get;private set;}internal bool Done=>bakes.Count>0&&bakes.All(b=>b.Op.isDone);internal int AgentCount=>bakes.Count;public string Fingerprint{get;}
 internal NavigationLayer(LocationDefinition d){Fingerprint=d.CollisionFingerprint();roots.Keep(sources);foreach(var b in d.Boxes.Where(b=>b.Solid))sources.Add(new NavMeshBuildSource{shape=NavMeshBuildSourceShape.Box,size=new Vector3(b.Size[0],b.Size[1],b.Size[2]),transform=Matrix4x4.TRS(new Vector3(b.Center[0],b.Center[1],b.Center[2]),Quaternion.identity,Vector3.one),area=b.Kind=="floor"?0:1});var solids=d.Boxes.Where(b=>b.Solid).ToArray();var lo=new Vector3(solids.Min(b=>b.Center[0]-b.Size[0]/2)-2,-2,solids.Min(b=>b.Center[2]-b.Size[2]/2)-2);var hi=new Vector3(solids.Max(b=>b.Center[0]+b.Size[0]/2)+2,8,solids.Max(b=>b.Center[2]+b.Size[2]/2)+2);int count=NavMesh.GetSettingsCount();if(count<1||count>16)throw new InvalidOperationException("Native navigation agents unavailable");
 try{for(int i=0;i<count;i++){var settings=NavMesh.GetSettingsByIndex(i);if(settings.agentRadius<=0||settings.agentHeight<=0)continue;if(settings.agentRadius>d.Agent.Radius||settings.agentHeight>d.Agent.Height)continue;var data=new NavMeshData(settings.agentTypeID){name="Reserve."+settings.agentTypeID,position=Vector3.zero,rotation=Quaternion.identity};roots.Keep(data);var op=NavMeshBuilder.UpdateNavMeshDataAsync(data,settings,sources,new Bounds((lo+hi)*.5f,hi-lo));if(op==null)throw new InvalidOperationException("Native NavMesh bake did not start");roots.Keep(op);bakes.Add(new Bake{Data=data,Op=op,AgentId=settings.agentTypeID});}if(bakes.Count==0)throw new InvalidOperationException("Layout does not fit the game's navigation agents");}catch{Dispose();throw;}}
 // Installed SamplePosition(..., NavMeshQueryFilter) uses ldarga on a reference-type wrapper.
 // SamplePositionFilter preserves agent/mask and calls the native injected implementation directly.
 internal void Publish(){if(!Done)throw new InvalidOperationException("Navigation bake is incomplete");if(Validated)return;foreach(var b in bakes){b.Instance=NavMesh.AddNavMeshData(b.Data);b.Published=b.Instance.valid;if(!b.Published)throw new InvalidOperationException("Native NavMesh registration failed");var anchors=new Dictionary<string,Vector3>();foreach(var a in Content.Map.Anchors){var p=new Vector3(a.Position[0],0,a.Position[2]);if(!NavMesh.SamplePositionFilter(p,out var hit,1f,b.AgentId,1)||Vector3.Distance(p,hit.position)>1f)throw new InvalidOperationException("Native navigation point unavailable: "+a.Id);anchors[a.Id]=hit.position;}
 foreach(var entry in Content.Map.Anchors.Where(a=>a.Kind=="player"))foreach(var exit in Content.Map.Anchors.Where(a=>a.Kind=="exit"))CheckPath(anchors[entry.Id],anchors[exit.Id],b.AgentId);
 }

 Validated=true;Trace.Data["nativeNavigationValidated"]=new{agents=bakes.Select(b=>b.AgentId).ToArray(),anchorChecks=Content.Map.Anchors.Length*bakes.Count,extractionRoutes=8*bakes.Count};}
 static unsafe void CheckPath(Vector3 from,Vector3 to,int agentId){var query=new NavMeshQuery(NavMeshWorld.GetDefaultWorld(),Allocator.Temp,8192);try{var start=query.MapLocation(from,Vector3.one,agentId,1);var end=query.MapLocation(to,Vector3.one,agentId,1);if(!query.IsValid(start)||!query.IsValid(end))throw new InvalidOperationException("Invalid path endpoint");var status=NavMeshQuery.BeginFindPath(query.m_NavMeshQuery,start,end,1,null);int total=0;while((status&PathQueryStatus.InProgress)!=0&&total<32768){status=query.UpdateFindPath(1024,out int used);total+=Math.Max(1,used);}if((status&PathQueryStatus.Success)==0||(status&(PathQueryStatus.PartialResult|PathQueryStatus.OutOfNodes|PathQueryStatus.Failure))!=0)throw new InvalidOperationException("Native extraction path search failed");status=query.EndFindPath(out int size);if((status&PathQueryStatus.Success)==0||size<1||size>8192||(status&PathQueryStatus.PartialResult)!=0)throw new InvalidOperationException("Native extraction path is partial");var path=stackalloc PolygonId[size];int written=NavMeshQuery.GetPathResult(query.m_NavMeshQuery,path,size);if(written!=size||!path[size-1].Equals(end.polygon))throw new InvalidOperationException("Native extraction path endpoint mismatch");}finally{query.Dispose();}}
 static readonly List<NavigationLayer> retired=new();bool disposed;
 public void Dispose(){if(disposed)return;disposed=true;foreach(var b in bakes){if(!b.Op.isDone)NavMeshBuilder.Cancel(b.Data);if(b.Published){b.Instance.Remove();b.Published=false;}}if(bakes.Any(b=>!b.Op.isDone)){retired.Add(this);return;}Free();}
 void Free(){foreach(var b in bakes)if(b.Data!=null)UnityEngine.Object.Destroy(b.Data);bakes.Clear();roots.Dispose();}
 internal static void CollectRetired(){for(int i=retired.Count-1;i>=0;i--)if(retired[i].bakes.All(b=>b.Op.isDone)){retired[i].Free();retired.RemoveAt(i);}}
}
